import{_ as e,o as i,c as o,ah as a}from"./chunks/framework.D4KxWb5R.js";const u=JSON.parse('{"title":"Indicator supervision","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/administration/indicators.md","filePath":"src/en/guide/administration/indicators.md"}'),n={name:"en/guide/administration/indicators.md"};function r(s,t,d,c,h,l){return i(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="indicator-supervision" tabindex="-1">Indicator supervision <a class="header-anchor" href="#indicator-supervision" aria-label="Permalink to &quot;Indicator supervision&quot;">​</a></h1><p><strong>Administration → Supervision</strong> shows the consolidated indicators reported by each product. Open to the CEO, Product Operations and Finance.</p><p>M&#39;City IQ holds only <strong>aggregated values</strong>, never a product&#39;s operational detail: that is viewed in the product&#39;s back-office.</p><h2 id="reading-the-supervision" tabindex="-1">Reading the supervision <a class="header-anchor" href="#reading-the-supervision" aria-label="Permalink to &quot;Reading the supervision&quot;">​</a></h2><p>For each active indicator, the page shows:</p><ul><li>its window (e.g. &quot;30-day window&quot;);</li><li>for each source product, the <strong>last value</strong> reported, its date and, where relevant, its <strong>breakdown</strong> (by activity domain, for example);</li><li>a <strong>total</strong>, only for additive indicators (sum). Distinct users or ratios don&#39;t add up from one product to another.</li></ul><p>&quot;Not reported yet&quot; marks a source product that hasn&#39;t sent anything yet.</p><h2 id="the-starting-indicators" tabindex="-1">The starting indicators <a class="header-anchor" href="#the-starting-indicators" aria-label="Permalink to &quot;The starting indicators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Indicator</th><th>Aggregation</th></tr></thead><tbody><tr><td>Active users (<code>active_users</code>)</td><td>Distinct count</td></tr><tr><td>Active providers and sellers (<code>active_providers</code>)</td><td>Distinct count</td></tr><tr><td>Published alerts (<code>published_alerts</code>)</td><td>Sum</td></tr><tr><td>Activity by domain (<code>activity_by_domain</code>)</td><td>Sum, with breakdown</td></tr></tbody></table><p>The CEO chooses which products report each indicator, and adds new ones, in <a href="./settings.html#indicator-definitions">Indicator definitions</a>.</p><h2 id="when-values-stop-coming-in" tabindex="-1">When values stop coming in <a class="header-anchor" href="#when-values-stop-coming-in" aria-label="Permalink to &quot;When values stop coming in&quot;">​</a></h2><p>In polling mode, if collection fails three times in a row, the CEO and the product&#39;s teams are notified. The <a href="./logs.html">sync log</a> shows each poll and its error; the CEO can run a collection with <strong>Poll now</strong> on the product&#39;s <strong>API integration</strong> page.</p>',12)])])}const g=e(n,[["render",r]]);export{u as __pageData,g as default};
